// The C header guard and preprocessor checks are intentionally omitted.
// MONITOR_NAME must be supplied by the generated model.  The following names
// correspond to CONCATENATE(automaton_, MONITOR_NAME),
// CONCATENATE(event_max_, MONITOR_NAME), CONCATENATE(state_max_, MONITOR_NAME),
// CONCATENATE(events_, MONITOR_NAME), and CONCATENATE(states_, MONITOR_NAME).

/* model_get_state_name - return the (string) name of the given state */
#[inline]
pub unsafe fn model_get_state_name(state: states) -> *mut ::core::ffi::c_char {
    if (state as isize) < 0 || (state as isize) >= state_max_MONITOR_NAME as isize {
        return b"INVALID\0".as_ptr() as *mut ::core::ffi::c_char;
    }

    automaton_MONITOR_NAME.state_names[state as usize] as *mut ::core::ffi::c_char
}

/* model_get_event_name - return the (string) name of the given event */
#[inline]
pub unsafe fn model_get_event_name(event: events) -> *mut ::core::ffi::c_char {
    if (event as isize) < 0 || (event as isize) >= event_max_MONITOR_NAME as isize {
        return b"INVALID\0".as_ptr() as *mut ::core::ffi::c_char;
    }

    automaton_MONITOR_NAME.event_names[event as usize] as *mut ::core::ffi::c_char
}

/* model_get_initial_state - return the automaton's initial state */
#[inline]
pub unsafe fn model_get_initial_state() -> states {
    automaton_MONITOR_NAME.initial_state
}

/*
 * model_get_next_state - process an automaton event occurrence
 *
 * Given the current state (curr_state) and the event (event), returns
 * the next state, or INVALID_STATE in case of error.
 */
#[inline]
pub unsafe fn model_get_next_state(curr_state: states, event: events) -> states {
    if (curr_state as isize) < 0 || (curr_state as isize) >= state_max_MONITOR_NAME as isize {
        return INVALID_STATE;
    }

    if (event as isize) < 0 || (event as isize) >= event_max_MONITOR_NAME as isize {
        return INVALID_STATE;
    }

    automaton_MONITOR_NAME.function[curr_state as usize][event as usize]
}

/* model_is_final_state - check if the given state is a final state */
#[inline]
pub unsafe fn model_is_final_state(state: states) -> bool {
    if (state as isize) < 0 || (state as isize) >= state_max_MONITOR_NAME as isize {
        return false;
    }

    automaton_MONITOR_NAME.final_states[state as usize]
}

